"""Row and vector evaluation of NetNomos formulas over prepared window frames.

All arithmetic is exact integer arithmetic on ``int64`` columns: sums may cross
fields and slots, scaling is a plain product, and neither wraps nor saturates.
Intermediate values need not belong to any declared domain.
"""
from __future__ import annotations

from typing import Any, Iterable, Mapping

import numpy as np

from netnomos.ast import (
    BinaryTerm,
    BoolAnd,
    BoolConst,
    BoolNot,
    BoolOr,
    Compare,
    Constant,
    Exists,
    Formula,
    ForAll,
    FuncCall,
    Implies,
    IndexedRef,
    SymbolRef,
    Term,
    formula_to_string,
)
from netnomos.dataset import PreparedDataset

#: Internal comparator spellings mapped onto exact integer numpy comparisons.
COMPARATORS = {
    "=": np.equal,
    "!=": np.not_equal,
    "<": np.less,
    "<=": np.less_equal,
    ">": np.greater,
    ">=": np.greater_equal,
}

Env = Mapping[str, Any]


def compare_values(op: str, left: Any, right: Any) -> bool:
    """Exact scalar comparison used by the row-wise reference evaluator."""
    if op == "=":
        return bool(left == right)
    if op == "!=":
        return bool(left != right)
    if op == ">":
        return bool(left > right)
    if op == ">=":
        return bool(left >= right)
    if op == "<":
        return bool(left < right)
    if op == "<=":
        return bool(left <= right)
    raise ValueError(f"Unsupported comparator: {op}")


def resolve_indexed_name(
    term: IndexedRef, env: Env, context_families: Mapping[str, list[str]]
) -> str:
    index = env.get(term.index, term.index)
    if isinstance(index, str) and index.isdigit():
        index = int(index)
    if not isinstance(index, int):
        raise ValueError(
            f"Indexed reference {formula_to_string(Compare('=', term, Constant(0)))} needs an integer index"
        )
    if term.base not in context_families:
        raise KeyError(f"Unknown context family: {term.base}")
    return context_families[term.base][index]


# --------------------------------------------------------------------------- rows
def evaluate_term_row(
    term: Term, row: Mapping[str, Any], context_families: Mapping[str, list[str]], env: Env | None = None
) -> Any:
    env = env or {}
    if isinstance(term, Constant):
        return term.value
    if isinstance(term, SymbolRef):
        return row[term.name]
    if isinstance(term, IndexedRef):
        return row[resolve_indexed_name(term, env, context_families)]
    if isinstance(term, BinaryTerm):
        left = evaluate_term_row(term.left, row, context_families, env)
        right = evaluate_term_row(term.right, row, context_families, env)
        if term.op == "+":
            return left + right
        if term.op == "-":
            return left - right
        if term.op == "*":
            return left * right
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        values = [evaluate_term_row(arg, row, context_families, env) for arg in term.args]
        name = term.name.lower()
        if name == "min":
            return min(values)
        if name == "max":
            return max(values)
        if name == "sum":
            return sum(values)
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def evaluate_formula_row(
    formula: Formula,
    row: Mapping[str, Any],
    context_families: Mapping[str, list[str]],
    env: Env | None = None,
) -> bool:
    env = env or {}
    if isinstance(formula, BoolConst):
        return bool(formula.value)
    if isinstance(formula, Compare):
        left = evaluate_term_row(formula.left, row, context_families, env)
        right = evaluate_term_row(formula.right, row, context_families, env)
        return compare_values(formula.op, left, right)
    if isinstance(formula, BoolNot):
        return not evaluate_formula_row(formula.value, row, context_families, env)
    if isinstance(formula, BoolAnd):
        return all(evaluate_formula_row(value, row, context_families, env) for value in formula.values)
    if isinstance(formula, BoolOr):
        return any(evaluate_formula_row(value, row, context_families, env) for value in formula.values)
    if isinstance(formula, Implies):
        return (not evaluate_formula_row(formula.left, row, context_families, env)) or evaluate_formula_row(
            formula.right, row, context_families, env
        )
    if isinstance(formula, ForAll):
        return all(
            evaluate_formula_row(formula.body, row, context_families, {**env, formula.variable: value})
            for value in formula.domain
        )
    if isinstance(formula, Exists):
        return any(
            evaluate_formula_row(formula.body, row, context_families, {**env, formula.variable: value})
            for value in formula.domain
        )
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")


# ------------------------------------------------------------------------ vectors
def evaluate_term_vector(term: Term, prepared: PreparedDataset, env: Env | None = None) -> Any:
    """Vectorised term value: an ``int64`` column, or an exact Python integer."""
    env = env or {}
    if isinstance(term, Constant):
        return int(term.value)
    if isinstance(term, SymbolRef):
        return prepared.column(term.name)
    if isinstance(term, IndexedRef):
        return prepared.column(resolve_indexed_name(term, env, prepared.context_families))
    if isinstance(term, BinaryTerm):
        left = evaluate_term_vector(term.left, prepared, env)
        right = evaluate_term_vector(term.right, prepared, env)
        if term.op == "+":
            return np.add(left, right, dtype=np.int64)
        if term.op == "-":
            return np.subtract(left, right, dtype=np.int64)
        if term.op == "*":
            return np.multiply(left, right, dtype=np.int64)
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        name = term.name.lower()
        values = [evaluate_term_vector(arg, prepared, env) for arg in term.args]
        if name == "sum":
            total: Any = 0
            for value in values:
                total = np.add(total, value, dtype=np.int64)
            return total
        if name in {"min", "max"}:
            stacked = np.stack(np.broadcast_arrays(*(np.asarray(value, dtype=np.int64) for value in values)))
            reduce = np.minimum.reduce if name == "min" else np.maximum.reduce
            return reduce(stacked, axis=0)
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def evaluate_formula_vector(
    formula: Formula, prepared: PreparedDataset, env: Env | None = None
) -> np.ndarray:
    """Truth value of ``formula`` for every row of ``prepared`` as a bool column."""
    env = env or {}
    length = prepared.length
    if isinstance(formula, BoolConst):
        return np.full(length, bool(formula.value), dtype=bool)
    if isinstance(formula, Compare):
        comparator = COMPARATORS[formula.op]
        left = evaluate_term_vector(formula.left, prepared, env)
        right = evaluate_term_vector(formula.right, prepared, env)
        result = comparator(left, right)
        if not isinstance(result, np.ndarray):
            return np.full(length, bool(result), dtype=bool)
        return result.view(np.bool_) if result.dtype == np.bool_ else result.astype(bool, copy=False)
    if isinstance(formula, BoolNot):
        return ~evaluate_formula_vector(formula.value, prepared, env)
    if isinstance(formula, BoolAnd):
        return _reduce_bool(formula.values, prepared, env, np.logical_and, True)
    if isinstance(formula, BoolOr):
        return _reduce_bool(formula.values, prepared, env, np.logical_or, False)
    if isinstance(formula, Implies):
        left = evaluate_formula_vector(formula.left, prepared, env)
        right = evaluate_formula_vector(formula.right, prepared, env)
        return (~left) | right
    if isinstance(formula, (ForAll, Exists)):
        identity = isinstance(formula, ForAll)
        accumulator: np.ndarray | None = None
        for value in formula.domain:
            body = evaluate_formula_vector(formula.body, prepared, {**env, formula.variable: value})
            accumulator = body.copy() if accumulator is None else (
                (accumulator & body) if identity else (accumulator | body)
            )
        if accumulator is None:
            return np.full(length, identity, dtype=bool)
        return accumulator
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")


def _reduce_bool(
    values: Iterable[Formula],
    prepared: PreparedDataset,
    env: Env,
    operation: Any,
    identity: bool,
) -> np.ndarray:
    accumulator: np.ndarray | None = None
    for value in values:
        child = evaluate_formula_vector(value, prepared, env)
        accumulator = child if accumulator is None else operation(accumulator, child)
    if accumulator is None:
        return np.full(prepared.length, identity, dtype=bool)
    return accumulator


def evaluate_formula(formula: Formula, prepared: PreparedDataset) -> np.ndarray:
    """Public vector entry point kept for callers of the original core API."""
    return evaluate_formula_vector(formula, prepared)
